INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1400, 'confidentiality agreement', '/ˌkɒnfɪˌdenʃiˈæləti əˈɡriːmənt/', 'noun', '{"zh-TW":["保密協議"],"en":["a contract requiring parties to keep information private"]}', NULL, 'sign a confidentiality agreement / breach a confidentiality agreement', '[{"en":"All employees must sign a confidentiality agreement on joining.","zh-TW":"所有員工在入職時必須簽署保密協議。"},{"en":"The confidentiality agreement covers product development plans.","zh-TW":"保密協議涵蓋產品開發計劃。"}]', '{"abbreviation":"NDA"}', NULL, 5, 1400, NULL),
(1401, 'confidentiality clause', '/ˌkɒnfɪdenʃiˈælɪti klɔːz/', 'noun', '{"zh-TW":["保密條款"],"en":["a contract provision requiring parties to keep designated information secret"]}', NULL, 'include a confidentiality clause / enforce a confidentiality clause', '[{"en":"A confidentiality clause protects trade secrets during negotiations.","zh-TW":"保密條款在談判期間保護商業機密。"},{"en":"Breach of the confidentiality clause may result in significant penalties.","zh-TW":"違反保密條款可能導致重大罰款。"}]', '{"synonym":"non-disclosure clause"}', NULL, 5, 1401, NULL),
(1402, 'confine', '/kənˈfaɪn/', 'verb', '{"zh-TW":["限制；局限於"],"en":["to keep or restrict within certain limits"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"fine","meaning":"end/limit (邊界)"},"logic":"完全限制在邊界內，即「限制」。"}', 'confine to / be confined to', '[{"en":"The discussion should be confined to budget matters.","zh-TW":"討論應限制在預算事項。"},{"en":"The problem is not confined to one department.","zh-TW":"問題不僅限於一個部門。"}]', NULL, NULL, 3, 1402, NULL),
(1403, 'confirm', '/kənˈfɜːrm/', 'verb', '{"zh-TW":["確認；證實","確認"],"en":["to establish the truth or correctness of","to establish the truth of something"]}', '{"prefix":{"text":"con-","meaning":"fully (完全)"},"root":{"text":"firm","meaning":"firm/strong (堅固)"},"logic":"使完全堅固確定，即「確認」。"}', 'confirm a booking/order/appointment; confirm a booking / confirm that / please confirm', '[{"en":"Please confirm your attendance by Friday.","zh-TW":"請在週五前確認您的出席。"},{"en":"The spokesperson confirmed the merger announcement.","zh-TW":"發言人確認了合併公告。"},{"en":"Please confirm your reservation by email.","zh-TW":"請透過電子郵件確認您的預訂。"},{"en":"The test results confirmed the diagnosis.","zh-TW":"檢驗結果確認了診斷。"}]', '{"noun":"confirmation"}', NULL, 3, 1403, 17),
(1404, 'confirmation', '/ˌkɒnfɜːˈmeɪʃən/', 'noun', '{"zh-TW":["確認；確認書"],"en":["a statement confirming a booking or reservation"]}', NULL, 'booking confirmation / confirmation number', '[{"en":"You will receive a confirmation email after booking.","zh-TW":"預訂後您將收到確認電子郵件。"},{"en":"Please bring your confirmation number to the front desk.","zh-TW":"請攜帶確認號碼前往前台。"}]', '{"verb":"confirm","adjective":"confirmed"}', NULL, 4, 1404, NULL),
(1405, 'confirmation bias', '/''kɒnfərˌmeɪʃən ˌbaɪəs/', 'noun', '{"zh-TW":["確認偏誤；確認偏見"],"en":["the tendency to search for, interpret, or remember information in a way that confirms one''s existing beliefs"]}', NULL, 'avoid confirmation bias / fall victim to confirmation bias / confirmation bias in research', '[{"en":"Investors are warned against confirmation bias, which can lead to poor financial decisions.","zh-TW":"投資者被警告要避免確認偏誤，這可能導致糟糕的財務決策。"},{"en":"News consumption patterns often reflect confirmation bias, with people preferring sources that validate their views.","zh-TW":"新聞消費模式通常反映確認偏誤，人們偏好驗證其觀點的來源。"}]', '{"noun":"bias","adjective":"biased"}', NULL, 5, 1405, NULL),
(1406, 'conflate', '/kənˈfleɪt/', 'verb', '{"zh-TW":["混淆；把…混為一談"],"en":["to combine two or more things, often incorrectly"]}', NULL, 'conflate two issues / conflate concepts / conflate data', '[{"en":"Be careful not to conflate correlation with causation.","zh-TW":"注意不要將相關性與因果關係混為一談。"},{"en":"The report conflated several distinct economic indicators.","zh-TW":"該報告將幾個不同的經濟指標混為一談。"}]', '{"noun":"conflation"}', NULL, 3, 1406, NULL),
(1407, 'conflict', '/ˈkɒnflɪkt/', 'noun', '{"zh-TW":["衝突；矛盾"],"en":["a serious disagreement or argument","a serious disagreement","a prolonged struggle"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"flict","meaning":"strike (打擊)"},"logic":"一起打擊碰撞，即「衝突」。"}', 'conflict of interest / resolve a conflict; conflict of interest / armed conflict / resolve a conflict', '[{"en":"There is a conflict of interest in this situation.","zh-TW":"在這種情況下存在利益衝突。"},{"en":"The manager helped resolve the conflict between teams.","zh-TW":"經理幫助解決了團隊之間的衝突。"},{"en":"There is a conflict between the two departments.","zh-TW":"兩個部門之間有衝突。"},{"en":"The conflict lasted for several years.","zh-TW":"衝突持續了好幾年。"}]', '{"adjective":"conflicting","verb":"conflict"}', NULL, 3, 1407, NULL),
(1408, 'conflict of interest', '/ˈkɒnflɪkt əv ˈɪntrəst/', 'noun', '{"zh-TW":["利益衝突"],"en":["a situation where personal interests could improperly influence professional judgment"]}', NULL, 'declare a conflict of interest / avoid conflicts of interest', '[{"en":"Board members must declare any conflict of interest before voting.","zh-TW":"董事會成員在投票前必須申報任何利益衝突。"},{"en":"She recused herself from the decision due to a conflict of interest.","zh-TW":"她因利益衝突而迴避了該決定。"}]', NULL, NULL, 5, 1408, NULL),
(1409, 'conflict resolution', '/ˈkɒnflɪkt ˌrezəˈluːʃən/', 'noun', '{"zh-TW":["衝突解決；調解"],"en":["the process of resolving a dispute or disagreement"]}', NULL, 'conflict resolution process / workplace conflict resolution / conflict resolution skills', '[{"en":"Effective conflict resolution prevents disputes from escalating into litigation.","zh-TW":"有效的衝突解決防止糾紛升級為訴訟。"},{"en":"The HR department offers conflict resolution training to managers.","zh-TW":"人力資源部門為管理者提供衝突解決培訓。"}]', NULL, NULL, 5, 1409, NULL),
(1410, 'conform', '/kənˈfɔːrm/', 'verb', '{"zh-TW":["符合；遵從"],"en":["to comply with rules, standards, or conventions"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"form","meaning":"shape (形狀)"},"logic":"完全成為相同形狀，即「符合」。"}', 'conform to standards/regulations/expectations', '[{"en":"All products must conform to industry standards.","zh-TW":"所有產品必須符合行業標準。"},{"en":"The design conforms to local building regulations.","zh-TW":"設計符合當地建築法規。"}]', '{"noun":"conformity"}', NULL, 3, 1410, NULL),
(1411, 'confront', '/kənˈfrʌnt/', 'verb', '{"zh-TW":["面對；對抗"],"en":["to face a difficult situation or person"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"front","meaning":"face/forehead (面)"},"logic":"完全面對面，即「面對」。"}', 'confront a challenge/problem/issue', '[{"en":"Companies must confront the challenge of digital transformation.","zh-TW":"企業必須面對數位轉型的挑戰。"},{"en":"The CEO confronted the issue directly at the meeting.","zh-TW":"執行長在會議上直接面對了這個問題。"}]', '{"noun":"confrontation"}', NULL, 3, 1411, NULL),
(1412, 'conglomerate', '/kənˈɡlɒmərɪt/', 'noun', '{"zh-TW":["企業集團；綜合企業"],"en":["a large corporation made up of different businesses"]}', NULL, 'multinational conglomerate / media conglomerate', '[{"en":"The company grew into a multinational conglomerate.","zh-TW":"公司發展成為跨國企業集團。"},{"en":"The media conglomerate owns several TV stations.","zh-TW":"這家媒體集團擁有多個電視台。"}]', '{"noun":"conglomerate","noun2":"conglomeration"}', NULL, 4, 1412, NULL),
(1413, 'congress', '/ˈkɒŋɡrɛs/', 'noun', '{"zh-TW":["國會"],"en":["the national legislative body"]}', NULL, 'member of congress / congressional hearing', '[{"en":"Congress passed the new law.","zh-TW":"國會通過了新法律。"},{"en":"She was elected to Congress.","zh-TW":"她被選入了國會。"}]', '{"adjective":"congressional"}', NULL, 3, 1413, NULL),
(1414, 'congruence', '/ˈkɒŋɡruəns/', 'noun', '{"zh-TW":["一致性；一致"],"en":["agreement or harmony between things"]}', NULL, 'goal congruence / value congruence / achieve congruence', '[{"en":"Goal congruence between management and shareholders reduces agency costs.","zh-TW":"管理層與股東之間的目標一致性降低了代理成本。"},{"en":"Cultural congruence between partners facilitates successful mergers.","zh-TW":"合作夥伴之間的文化一致性有助於成功的合併。"}]', '{"adjective":"congruent","adverb":"congruently"}', NULL, 4, 1414, NULL),
(1415, 'conjecture', '/kənˈdʒektʃər/', 'noun', '{"zh-TW":["推測；猜想"],"en":["an opinion formed on the basis of incomplete information"]}', NULL, 'mere conjecture / reasonable conjecture / based on conjecture', '[{"en":"The claim is based on conjecture rather than data.","zh-TW":"這一說法基於推測而非數據。"},{"en":"Any conjecture should be tested against empirical evidence.","zh-TW":"任何推測都應以實證數據加以驗證。"}]', '{"verb":"conjecture","adjective":"conjectural"}', NULL, 4, 1415, NULL),
(1416, 'connect', 'kəˈnɛkt', 'verb', '{"zh-TW":["連接；聯繫","關聯"],"en":["to join together","to establish contact"]}', NULL, 'connect with clients/connect systems', '[{"en":"Let me connect you with the right department.","zh-TW":"讓我為您接通正確的部門。"}]', '{"noun":"connection","adjective":"connected","adverb":"connectedly"}', NULL, 3, 1416, NULL),
(1417, 'connecting flight', '/kəˈnɛktɪŋ flaɪt/', 'noun', '{"zh-TW":["轉機航班"],"en":["a flight requiring a change of planes"]}', NULL, 'catch a connecting flight / miss a connecting flight', '[{"en":"We have two hours before our connecting flight.","zh-TW":"我們在轉機前有兩小時。"},{"en":"Her connecting flight was delayed due to weather.","zh-TW":"她的轉機航班因天氣延誤。"}]', NULL, NULL, 5, 1417, NULL),
(1418, 'connecting rooms', '/kəˈnɛktɪŋ ruːmz/', 'noun', '{"zh-TW":["相通房間"],"en":["adjoining hotel rooms with a shared internal door"]}', NULL, 'book connecting rooms / connecting rooms for families', '[{"en":"We booked connecting rooms so the family could stay together.","zh-TW":"我們預訂了相通房間，方便全家住在一起。"},{"en":"Connecting rooms are ideal for families traveling with children.","zh-TW":"相通房間非常適合攜帶孩子旅行的家庭。"}]', NULL, NULL, 5, 1418, NULL),
(1419, 'connection', '/kəˈnɛkʃən/', 'noun', '{"zh-TW":["連接；關聯"],"en":["a link between things or people"]}', NULL, 'internet connection / personal connection', '[{"en":"I have a poor internet connection.","zh-TW":"我的網路連線很差。"},{"en":"There''s a connection between diet and health.","zh-TW":"飲食和健康之間有關聯。"}]', '{"verb":"connect","adjective":"connected"}', NULL, 4, 1419, NULL),
(1420, 'connoisseur', '/ˌkɒnəˈsɜːr/', 'noun', '{"zh-TW":["鑑賞家；行家"],"en":["an expert judge in matters of taste, especially in art and food"]}', NULL, 'art connoisseur / wine connoisseur / music connoisseur', '[{"en":"A connoisseur instantly recognized the painting as a forgery.","zh-TW":"一位鑑賞家立即認出這幅畫是贗品。"},{"en":"The auction attracted collectors and connoisseurs from around the world.","zh-TW":"拍賣吸引了來自世界各地的收藏家和鑑賞家。"}]', NULL, NULL, 4, 1420, NULL),
(1421, 'connotation', '/ˌkɒnəˈteɪʃən/', 'noun', '{"zh-TW":["含意；附加意義"],"en":["an idea or feeling associated with a word beyond its literal meaning"]}', NULL, 'negative connotation / positive connotation / cultural connotation', '[{"en":"The word ''discipline'' has both positive and negative connotations.","zh-TW":"「紀律」這個詞既有正面也有負面的含意。"},{"en":"Be aware of cultural connotations when translating terms.","zh-TW":"翻譯術語時要注意文化含意。"}]', '{"verb":"connote","adjective":"connotative"}', NULL, 4, 1421, NULL),
(1422, 'conscious', '/ˈkɒnʃəs/', 'adjective', '{"zh-TW":["有意識的；自覺的"],"en":["aware of and responding to surroundings","aware of and responding to one''s surroundings"]}', '{"prefix":{"text":"con-","meaning":"with (帶有)"},"root":{"text":"sci","meaning":"know (知道)"},"suffix":{"text":"-ous","meaning":"having (具有)"},"logic":"帶有知覺的，即「有意識的」。"}', 'conscious effort / self-conscious; conscious effort / conscious decision / self-conscious', '[{"en":"She made a conscious effort to be kind.","zh-TW":"她有意識地努力做到友善。"},{"en":"He was barely conscious after the accident.","zh-TW":"事故後他幾乎失去意識。"},{"en":"She made a conscious effort to be polite.","zh-TW":"她有意識地努力保持禮貌。"},{"en":"He was barely conscious after the accident.","zh-TW":"事故後他幾乎沒有意識了。"}]', '{"noun":"consciousness","adverb":"consciously"}', NULL, 3, 1422, NULL),
(1423, 'consecutive', '/kənˈsekjʊtɪv/', 'adjective', '{"zh-TW":["連續的"],"en":["following each other without interruption"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"secut","meaning":"follow (跟隨)"},"suffix":{"text":"-ive","meaning":"having quality (具有特質)"},"logic":"一起跟隨的，即「連續的」。"}', 'consecutive years/months/quarters', '[{"en":"Revenue has grown for five consecutive quarters.","zh-TW":"營收已連續五個季度成長。"},{"en":"She won the award for three consecutive years.","zh-TW":"她連續三年獲得該獎項。"}]', '{"adverb":"consecutively"}', NULL, 4, 1423, NULL),
(1424, 'consensus', '/kənˈsɛnsəs/', 'noun', '{"zh-TW":["共識；一致意見"],"en":["general agreement among a group"]}', NULL, 'reach a consensus / build consensus', '[{"en":"The team reached a consensus on the new strategy.","zh-TW":"團隊就新策略達成了共識。"},{"en":"Building consensus takes time but leads to better outcomes.","zh-TW":"建立共識需要時間，但會帶來更好的結果。"}]', '{"adjective":"consensual"}', NULL, 3, 1424, NULL),
(1425, 'consensus building', '/kənˈsensəs ˈbɪldɪŋ/', 'noun', '{"zh-TW":["共識建立"],"en":["the process of reaching broad agreement among stakeholders"]}', NULL, 'consensus building process / support consensus building / effective consensus building', '[{"en":"Effective consensus building requires listening and compromise.","zh-TW":"有效的共識建立需要傾聽和妥協。"},{"en":"The facilitator guided the group through a structured consensus building exercise.","zh-TW":"主持人引導小組進行了結構化的共識建立練習。"}]', NULL, NULL, 5, 1425, NULL),
(1426, 'consensus decision', '/''kənˌsensəs dɪˌsɪʒən/', 'noun', '{"zh-TW":["共識決定；共同決策"],"en":["a decision reached by the agreement of all members of a group"]}', NULL, 'reach a consensus decision / consensus decision process / make a consensus decision', '[{"en":"The committee reached a consensus decision after hours of debate.","zh-TW":"委員會在幾小時的辯論後達成了共識決定。"},{"en":"Making a consensus decision can be time-consuming but leads to better team commitment.","zh-TW":"做出共識決定可能耗時，但能帶來更好的團隊承諾。"}]', '{"noun":"consensus"}', NULL, 5, 1426, NULL),
(1427, 'consent', '/kənˈsent/', 'noun', '{"zh-TW":["同意；許可"],"en":["permission or agreement to do something"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sent","meaning":"feel (感覺)"},"logic":"一起有相同感覺，即「同意」。"}', 'give consent / informed consent / without consent', '[{"en":"Written consent is required before processing personal data.","zh-TW":"處理個人資料前需要書面同意。"},{"en":"The change was made without employee consent.","zh-TW":"變更未經員工同意就進行了。"}]', NULL, NULL, 3, 1427, NULL),
(1428, 'consent decree', '/kənˈsent dɪˈkriː/', 'noun', '{"zh-TW":["同意令；和解令"],"en":["a court-approved agreement to resolve a lawsuit without a trial"]}', NULL, 'enter a consent decree / comply with consent decree / consent decree terms', '[{"en":"The company entered a consent decree requiring it to change its business practices.","zh-TW":"公司簽署了要求其改變商業行為的同意令。"},{"en":"Consent decrees are commonly used to resolve antitrust violations.","zh-TW":"同意令常用於解決反托拉斯違規問題。"}]', NULL, NULL, 5, 1428, NULL),
(1429, 'consequence', '/ˈkɒnsɪkwəns/', 'noun', '{"zh-TW":["後果；結果"],"en":["a result or effect of an action or condition"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"sequ","meaning":"follow (跟隨)"},"suffix":{"text":"-ence","meaning":"state (狀態)"},"logic":"完全跟隨而來的，即「後果」。"}', 'as a consequence / face consequences / serious consequences', '[{"en":"As a consequence of the delay, costs increased significantly.","zh-TW":"由於延遲，成本大幅增加。"},{"en":"Failure to comply will have serious consequences.","zh-TW":"不遵守將會有嚴重後果。"}]', '{"adjective":"consequent","adverb":"consequently"}', NULL, 4, 1429, NULL),
(1430, 'consequential', '/ˌkɒnsɪˈkwenʃəl/', 'adjective', '{"zh-TW":["重要的；有重大後果的"],"en":["important; of significant consequence"]}', NULL, 'highly consequential / consequential decision / consequential mistake', '[{"en":"The leadership election was one of the most consequential in decades.","zh-TW":"這次領導層選舉是幾十年來最具重大後果的選舉之一。"},{"en":"A consequential error in the contract led to costly litigation.","zh-TW":"合約中的一個重要錯誤導致了代價高昂的訴訟。"}]', '{"adverb":"consequentially"}', NULL, 5, 1430, NULL),
(1431, 'consequently', '/''kɒnsɪkwəntli/', 'adverb', '{"zh-TW":["因此；結果地"],"en":["as a result; therefore"]}', NULL, 'and consequently / consequently failed / consequently improved', '[{"en":"The project ran over budget, and consequently, the deadline had to be extended.","zh-TW":"項目超出預算，因此不得不延長截止日期。"},{"en":"She took extra courses to strengthen her skills and, consequently, received a promotion.","zh-TW":"她參加了額外的課程以加強技能，因此獲得了晉升。"}]', '{"adjective":"consequent"}', NULL, 4, 1431, NULL),
(1432, 'conservation', '/ˌkɒnsərˈveɪʃn/', 'noun', '{"zh-TW":["保育；保存"],"en":["the protection of natural resources"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"serv","meaning":"keep (保存)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"共同保存的過程，即「保育」。"}', 'wildlife conservation / energy conservation', '[{"en":"Wildlife conservation is critical for biodiversity.","zh-TW":"野生動物保育對生物多樣性至關重要。"},{"en":"Energy conservation reduces electricity bills.","zh-TW":"節約能源可以減少電費。"}]', '{"verb":"conserve","adjective":"conservative","noun2":"conservationist"}', NULL, 4, 1432, NULL),
(1433, 'conservative', '/kənˈsɜːrvətɪv/', 'adjective', '{"zh-TW":["保守的；謹慎的"],"en":["averse to change; cautious in estimate"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"serv","meaning":"keep (保持)"},"suffix":{"text":"-ative","meaning":"tending to (傾向)"},"logic":"傾向完全保持的，即「保守的」。"}', 'conservative estimate / conservative approach', '[{"en":"A conservative estimate puts the cost at $3 million.","zh-TW":"保守估計成本為300萬美元。"},{"en":"The company took a conservative approach to investing.","zh-TW":"公司採取保守的投資策略。"}]', NULL, NULL, 4, 1433, NULL),
(1434, 'consider', '/kənˈsɪdər/', 'verb', '{"zh-TW":["考慮；認為"],"en":["to think carefully about something"]}', NULL, 'consider doing / all things considered', '[{"en":"Please consider my proposal.","zh-TW":"請考慮我的提案。"},{"en":"She is considered an expert.","zh-TW":"她被認為是專家。"}]', '{"noun":"consideration","adjective":"considerable"}', NULL, 3, 1434, NULL),
(1435, 'considerable', '/kənˈsɪdərəbl/', 'adjective', '{"zh-TW":["相當大的；可觀的"],"en":["notably large in size, amount, or extent"]}', '{"prefix":{"text":"con-","meaning":"fully (完全)"},"root":{"text":"sider","meaning":"star (星)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠完全被考量的（重要的），即「相當大的」。"}', 'considerable amount/effort/experience', '[{"en":"The project requires considerable investment.","zh-TW":"該專案需要大量投資。"},{"en":"She has considerable experience in marketing.","zh-TW":"她在行銷方面有豐富的經驗。"}]', '{"adverb":"considerably"}', NULL, 4, 1435, NULL),
(1436, 'considerate', '/kənˈsɪdərət/', 'adjective', '{"zh-TW":["體貼的；考慮周到的"],"en":["careful not to inconvenience or harm others"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sider","meaning":"star (星)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"如同觀星般仔細考量他人，即「體貼的」。"}', 'considerate of others / thoughtful and considerate', '[{"en":"He is always considerate of other people''s feelings.","zh-TW":"他總是顧及他人的感受。"},{"en":"It was considerate of you to call first.","zh-TW":"你先打電話來很體貼。"}]', '{"noun":"consideration","verb":"consider"}', NULL, 4, 1436, NULL),
(1437, 'consideration', '/kənˌsɪdəˈreɪʃən/', 'noun', '{"zh-TW":["對價；報酬"],"en":["something of value exchanged between contracting parties"]}', NULL, 'valuable consideration / in consideration of', '[{"en":"The contract must include a valid consideration to be enforceable.","zh-TW":"合約必須包含有效的對價才能執行。"},{"en":"In consideration of payment, the service will begin immediately.","zh-TW":"作為付款的對價，服務將立即開始。"}]', '{"verb":"consider","adjective":"considerable"}', NULL, 5, 1437, NULL),
(1438, 'consignee', '/ˌkɒnsɪˈniː/', 'noun', '{"zh-TW":["收貨人"],"en":["the person or company to whom goods are shipped or delivered"]}', NULL, 'notify the consignee / consignee address', '[{"en":"The consignee must present the bill of lading to collect the cargo.","zh-TW":"收貨人必須提交提單才能提取貨物。"},{"en":"All shipping documents must clearly identify the consignee.","zh-TW":"所有運輸文件必須清楚地標明收貨人。"}]', '{"opposite":"consignor"}', NULL, 3, 1438, NULL),
(1439, 'consignment', '/kənˈsaɪnmənt/', 'noun', '{"zh-TW":["托運；一批貨物"],"en":["a batch of goods sent or delivered"]}', NULL, 'receive a consignment / consignment note', '[{"en":"A consignment of electronics arrived from the factory.","zh-TW":"一批電子產品從工廠運到了。"},{"en":"The consignment will be delivered within five business days.","zh-TW":"這批貨物將在五個工作日內送達。"}]', '{"verb":"consign","noun":"consignee"}', NULL, 4, 1439, NULL),
(1440, 'consignment note', '/kənˈsaɪnmənt noʊt/', 'noun', '{"zh-TW":["運貨單；托運單"],"en":["a document accompanying goods showing details of the shipment"]}', NULL, 'prepare a consignment note / attach the consignment note', '[{"en":"A consignment note was issued for each shipment.","zh-TW":"每批貨物都簽發了一份運貨單。"},{"en":"The consignment note details the contents, weight, and destination.","zh-TW":"運貨單詳列了內容物、重量和目的地。"}]', NULL, NULL, 5, 1440, NULL),
(1441, 'consignment stock', '/kənˈsaɪnmənt stɒk/', 'noun', '{"zh-TW":["寄售存貨"],"en":["goods held by a retailer but owned by the supplier until sold"]}', NULL, 'manage consignment stock / consignment stock agreement', '[{"en":"Consignment stock allows retailers to carry products with no upfront cost.","zh-TW":"寄售存貨使零售商可以在沒有前期成本的情況下持有產品。"},{"en":"The supplier reviews consignment stock levels monthly.","zh-TW":"供應商每月審查寄售存貨水平。"}]', NULL, NULL, 5, 1441, NULL),
(1442, 'consignor', '/''kɒnˈsaɪnər/', 'noun', '{"zh-TW":["發貨人；委託方"],"en":["a person or company that sends or delivers goods to another party"]}', NULL, 'consignor documentation / authorized consignor / consignor details', '[{"en":"The consignor provided all necessary documentation before the shipment was dispatched.","zh-TW":"發貨人在貨物發出之前提供了所有必要的文件。"},{"en":"As the consignor, the manufacturer was responsible for correct packaging and labeling.","zh-TW":"作為發貨人，製造商負責正確的包裝和標籤。"}]', NULL, NULL, 3, 1442, NULL),
(1443, 'consist', '/kənˈsɪst/', 'verb', '{"zh-TW":["由…組成"],"en":["to be composed or made up of"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sist","meaning":"stand (站)"},"logic":"一起站立的，即「組成」。"}', 'consist of / consist in', '[{"en":"The team consists of 15 experienced professionals.","zh-TW":"團隊由15位經驗豐富的專業人士組成。"},{"en":"The test consists of three sections.","zh-TW":"測驗由三個部分組成。"}]', '{"adjective":"consistent","noun":"consistency"}', NULL, 3, 1443, NULL),
(1444, 'consistent', '/kənˈsɪstənt/', 'adjective', '{"zh-TW":["一致的；持續的"],"en":["unchanging over time; compatible"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sist","meaning":"stand (站立)"},"suffix":{"text":"-ent","meaning":"being (…的)"},"logic":"站在一起不變的，即「一致的」。"}', 'consistent results / consistent with / remain consistent', '[{"en":"She has been consistent in her performance.","zh-TW":"她的表現一直很穩定。"},{"en":"The data is consistent with our hypothesis.","zh-TW":"數據與我們的假設一致。"}]', '{"noun":"consistency","adverb":"consistently"}', NULL, 4, 1444, 962),
(1445, 'consolidate', '/kənˈsɒlɪdeɪt/', 'verb', '{"zh-TW":["合併；鞏固"],"en":["to combine into a single more effective whole","to strengthen a position"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"solid","meaning":"solid (堅固)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使一起堅固，即「合併、鞏固」。"}', 'consolidate operations/position/power', '[{"en":"The company consolidated its three offices into one.","zh-TW":"公司將三個辦公室合併為一個。"},{"en":"We aim to consolidate our market position.","zh-TW":"我們旨在鞏固市場地位。"}]', '{"noun":"consolidation"}', NULL, 4, 1445, 659),
(1446, 'consolidated', '/''kənˌsɒlɪdeɪtɪd/', 'adjective', '{"zh-TW":["合併的；鞏固的；統一的"],"en":["made stronger or more solid; combined into a single unit"]}', NULL, 'consolidated report / consolidated balance sheet / consolidated effort', '[{"en":"The consolidated report gives a comprehensive overview of all subsidiaries.","zh-TW":"合併報告對所有子公司提供了全面的概覽。"},{"en":"A consolidated effort from all departments resulted in a successful product launch.","zh-TW":"所有部門的共同努力促成了成功的產品發布。"}]', '{"verb":"consolidate","noun":"consolidation","adverb":"consolidatedly"}', NULL, 4, 1446, NULL),
(1447, 'consolidation', '/kənˌsɒlɪˈdeɪʃən/', 'noun', '{"zh-TW":["整合；鞏固"],"en":["the merging of multiple businesses or operations into one"]}', NULL, 'industry consolidation / debt consolidation', '[{"en":"Industry consolidation has reduced competition.","zh-TW":"行業整合降低了競爭程度。"},{"en":"The consolidation of the two divisions improved efficiency.","zh-TW":"兩個部門的整合提高了效率。"}]', '{"verb":"consolidate","adjective":"consolidated"}', NULL, 5, 1447, 530),
(1448, 'consortium', '/kənˈsɔːrtiəm/', 'noun', '{"zh-TW":["聯盟；財團"],"en":["a group of companies working together"]}', NULL, 'form a consortium / industry consortium', '[{"en":"Three firms formed a consortium for the bid.","zh-TW":"三家公司組成聯盟參與競標。"},{"en":"The consortium invested in infrastructure.","zh-TW":"財團投資了基礎設施。"}]', '{"noun":"consortium","plural":"consortia"}', NULL, 4, 1448, 763),
(1449, 'constant', '/ˈkɒnstənt/', 'adjective', '{"zh-TW":["不斷的；恆定的"],"en":["happening all the time without stopping"]}', NULL, 'constant pressure / constant speed', '[{"en":"The noise was constant.","zh-TW":"噪音持續不斷。"},{"en":"She''s under constant pressure.","zh-TW":"她承受著持續的壓力。"}]', '{"adverb":"constantly","noun":"constancy"}', NULL, 3, 1449, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1450, 'constitute', '/ˈkɒnstɪtjuːt/', 'verb', '{"zh-TW":["構成；組成"],"en":["to be a part of a whole","to be equivalent to"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"stitut","meaning":"set up (建立)"},"logic":"一起建立起來的，即「構成」。"}', 'constitute a majority/threat/violation', '[{"en":"Foreign sales constitute 60% of total revenue.","zh-TW":"海外銷售構成總營收的60%。"},{"en":"This action may constitute a breach of contract.","zh-TW":"此行為可能構成違約。"}]', '{"noun":"constitution","adjective":"constitutional"}', NULL, 4, 1450, 660),
(1451, 'constitution', '/ˌkɒnstɪˈtjuːʃən/', 'noun', '{"zh-TW":["憲法"],"en":["the fundamental laws of a country"]}', NULL, 'written constitution / constitutional right', '[{"en":"The constitution guarantees basic rights.","zh-TW":"憲法保障基本權利。"},{"en":"It''s protected by the constitution.","zh-TW":"這受到憲法保護。"}]', '{"adjective":"constitutional"}', NULL, 4, 1451, NULL),
(1452, 'constraint', '/kənˈstreɪnt/', 'noun', '{"zh-TW":["限制；約束"],"en":["a limitation or restriction"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"strain","meaning":"bind/tighten (綁/拉緊)"},"suffix":{"text":"-t","meaning":"noun ending"},"logic":"完全綁緊的，即「限制」。"}', 'budget constraints / time constraints / within constraints', '[{"en":"Budget constraints limit what we can accomplish.","zh-TW":"預算限制了我們能完成的事。"},{"en":"We must work within these constraints.","zh-TW":"我們必須在這些限制內工作。"}]', '{"verb":"constrain"}', NULL, 4, 1452, NULL),
(1453, 'construct', '/kənˈstrʌkt/', 'verb', '{"zh-TW":["建造；構建"],"en":["to build or erect something"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"struct","meaning":"build (建造)"},"logic":"一起建造，即「建造」。"}', 'construct a building/argument/plan', '[{"en":"The new headquarters will be constructed next year.","zh-TW":"新總部將於明年建造。"},{"en":"The lawyer constructed a compelling argument.","zh-TW":"律師構建了一個有說服力的論點。"}]', '{"noun":"construction","adjective":"constructive"}', NULL, 3, 1453, 733),
(1454, 'construction', '/kənˈstrʌkʃən/', 'noun', '{"zh-TW":["建設；建造"],"en":["the process of building something"]}', NULL, 'under construction / construction site', '[{"en":"The building is under construction.","zh-TW":"大樓正在建設中。"},{"en":"Construction will be completed next year.","zh-TW":"建設將於明年完工。"}]', '{"verb":"construct","adjective":"constructive"}', NULL, 4, 1454, 305),
(1455, 'construction contract', '/kənˈstrʌkʃən ˈkɒntrækt/', 'noun', '{"zh-TW":["建設合約；施工合約"],"en":["a legally binding agreement defining terms for a construction project"]}', NULL, 'award a construction contract / construction contract terms', '[{"en":"The construction contract specified completion within 18 months.","zh-TW":"建設合約規定了在18個月內完工。"},{"en":"Disputes arising from construction contracts often proceed to arbitration.","zh-TW":"由建設合約引起的爭議通常進入仲裁程序。"}]', NULL, NULL, 5, 1455, NULL),
(1456, 'constructive', 'kənˈstrʌktɪv', 'adjective', '{"zh-TW":["建設性的；有益的","積極的"],"en":["intended to be helpful","positive and useful"]}', NULL, 'constructive feedback/constructive criticism', '[{"en":"Please provide constructive feedback.","zh-TW":"請提供建設性的反饋。"}]', '{"noun":"construction","adverb":"constructively"}', NULL, 4, 1456, 963),
(1457, 'constructive dismissal', '/kənˈstrʌktɪv dɪˈmɪsəl/', 'noun', '{"zh-TW":["逼迫辭職；推定解僱"],"en":["when an employer makes working conditions intolerable, forcing resignation"]}', NULL, 'claim constructive dismissal / constructive dismissal case', '[{"en":"She claimed constructive dismissal after her responsibilities were stripped away.","zh-TW":"她在職責被剝奪後提出了逼迫辭職的主張。"},{"en":"Constructive dismissal claims are difficult but winnable in court.","zh-TW":"逼迫辭職索賠在法庭上很困難但可以勝訴。"}]', NULL, NULL, 5, 1457, NULL),
(1458, 'constructive feedback', '/kənˈstrʌktɪv ˈfiːdbæk/', 'noun', '{"zh-TW":["建設性反饋"],"en":["helpful criticism aimed at improving performance or behavior"]}', NULL, 'give constructive feedback / receive constructive feedback', '[{"en":"Managers are trained to deliver constructive feedback effectively.","zh-TW":"管理者接受培訓以有效提供建設性反饋。"},{"en":"Constructive feedback helped her improve her presentation skills.","zh-TW":"建設性反饋幫助她改善了演講技巧。"}]', NULL, NULL, 5, 1458, NULL),
(1459, 'consulate', '/''kɒnsjʊlɪt/', 'noun', '{"zh-TW":["領事館"],"en":["the offices of a consul, responsible for looking after citizens abroad"]}', NULL, 'contact the consulate / consulate general / visit the consulate', '[{"en":"The consulate issued an emergency passport for the stranded traveler.","zh-TW":"領事館為滯留的旅客簽發了緊急護照。"},{"en":"Our consulate can assist with lost documents and legal issues abroad.","zh-TW":"我們的領事館可以協助處理在海外遺失文件和法律問題。"}]', NULL, NULL, 3, 1459, NULL),
(1460, 'consult', '/kənˈsʌlt/', 'verb', '{"zh-TW":["諮詢；查閱"],"en":["to seek information or advice from someone"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sult","meaning":"take counsel (取得建議)"},"logic":"一起取得建議，即「諮詢」。"}', 'consult with / consult a specialist', '[{"en":"You should consult a lawyer before signing.","zh-TW":"簽名前你應該諮詢律師。"},{"en":"The management consulted with employees on the change.","zh-TW":"管理層就變革與員工進行了諮詢。"}]', '{"noun":"consultant","noun2":"consultation"}', NULL, 3, 1460, 90),
(1461, 'consultant', '/kənˈsʌltənt/', 'noun', '{"zh-TW":["顧問；諮詢師"],"en":["an expert who provides professional advice to organizations"]}', NULL, 'management consultant / IT consultant / hire a consultant / outside consultant', '[{"en":"The company brought in a management consultant to review operations.","zh-TW":"公司聘請了管理顧問審查運營。"},{"en":"The consultant delivered recommendations within six weeks.","zh-TW":"顧問在六週內提供了建議。"}]', '{"plural":"consultants","verb":"consult","noun":"consultancy"}', NULL, 4, 1461, NULL),
(1462, 'consulting assignment', '/kənˈsʌltɪŋ əˈsaɪnmənt/', 'noun', '{"zh-TW":["諮詢任務；顧問委派"],"en":["a specific project or engagement undertaken by a consultant"]}', NULL, 'complete a consulting assignment / accept a consulting assignment', '[{"en":"The consulting assignment lasted six months and covered operations.","zh-TW":"諮詢任務持續了六個月並涵蓋了業務。"},{"en":"The firm accepted the consulting assignment on a fixed-fee basis.","zh-TW":"公司以固定費用基礎接受了諮詢任務。"}]', NULL, NULL, 5, 1462, NULL),
(1463, 'consulting fee', '/kənˈsʌltɪŋ fiː/', 'noun', '{"zh-TW":["諮詢費"],"en":["payment made to a consultant for professional advice and services"]}', NULL, 'pay a consulting fee / consulting fee structure', '[{"en":"The consulting fee was based on daily rate plus project deliverables.","zh-TW":"諮詢費基於日費率加上項目可交付成果。"},{"en":"Management consulting fees can represent a significant project cost.","zh-TW":"管理諮詢費可能代表顯著的項目成本。"}]', NULL, NULL, 5, 1463, NULL),
(1464, 'consulting fees', '/kənˈsʌltɪŋ fiːz/', 'noun', '{"zh-TW":["諮詢費"],"en":["fees paid to external consultants for advisory services"]}', NULL, 'pay consulting fees / negotiate consulting fees', '[{"en":"Consulting fees amounted to 200000 dollars for the project.","zh-TW":"項目的諮詢費共計20萬元。"},{"en":"The company reduced consulting fees by developing internal expertise.","zh-TW":"公司通過培養內部專業知識降低了諮詢費。"}]', NULL, NULL, 5, 1464, NULL),
(1465, 'consulting firm', '/kənˈsʌltɪŋ fɜːrm/', 'noun', '{"zh-TW":["諮詢公司"],"en":["a professional services organization providing expert advice to clients"]}', NULL, 'engage a consulting firm / consulting firm recommendation', '[{"en":"The company hired a consulting firm to review its operations.","zh-TW":"公司聘請了一家諮詢公司審查其業務。"},{"en":"Top consulting firms offer expertise across strategy, finance, and operations.","zh-TW":"頂級諮詢公司在戰略、財務和運營方面提供專業知識。"}]', NULL, NULL, 5, 1465, NULL),
(1466, 'consume', '/kənˈsjuːm/', 'verb', '{"zh-TW":["消費；消耗","消耗；消費"],"en":["to use up a resource","to eat or drink something","to use up; to eat or drink","to eat or drink"]}', '{"prefix":{"text":"con-","meaning":"completely (完全)"},"root":{"text":"sume","meaning":"take (拿取)"},"logic":"完全拿取用盡，即「消費」。"}', 'consume energy/resources/time; consume energy / consume food; consume energy / consume food / time-consuming', '[{"en":"The factory consumes large amounts of electricity.","zh-TW":"工廠消耗大量電力。"},{"en":"This process consumes too much time.","zh-TW":"這個流程消耗太多時間。"},{"en":"The factory consumes a lot of energy.","zh-TW":"工廠消耗大量能源。"},{"en":"Americans consume too much sugar.","zh-TW":"美國人攝取過多糖分。"},{"en":"Cars consume a lot of fuel.","zh-TW":"汽車消耗大量燃料。"},{"en":"Americans consume more sugar than recommended.","zh-TW":"美國人攝取的糖分超過建議量。"}]', '{"noun":"consumer","noun2":"consumption"}', NULL, 3, 1466, 91),
(1467, 'consumer', '/kənˈsjuːmər/', 'noun', '{"zh-TW":["消費者"],"en":["a person who purchases goods or services for personal use"]}', NULL, 'target consumer / consumer behavior', '[{"en":"Understanding consumer behavior is key to effective marketing.","zh-TW":"了解消費者行為是有效行銷的關鍵。"},{"en":"Consumer demand for eco-friendly products is growing.","zh-TW":"消費者對環保產品的需求不斷增長。"}]', '{"verb":"consume","noun2":"consumption","adjective":"consumer"}', NULL, 3, 1467, 306),
(1468, 'consumer behavior', '/''kənˌsjuːmər bɪˌheɪvjər/', 'noun', '{"zh-TW":["消費者行為"],"en":["the study of how people make decisions about what they buy, use, and dispose of"]}', NULL, 'analyze consumer behavior / understand consumer behavior / consumer behavior trends', '[{"en":"Understanding consumer behavior is essential for developing effective marketing strategies.","zh-TW":"理解消費者行為對於制定有效的行銷策略至關重要。"},{"en":"Social media has dramatically changed consumer behavior and purchasing patterns.","zh-TW":"社交媒體已顯著改變了消費者行為和購買模式。"}]', '{"noun":"consumer"}', NULL, 5, 1468, NULL),
(1469, 'consumer confidence', '/kənˈsjuːmər ˈkɒnfɪdəns/', 'noun', '{"zh-TW":["消費者信心"],"en":["the degree to which consumers feel confident about their financial prospects"]}', NULL, 'measure consumer confidence / high consumer confidence', '[{"en":"High consumer confidence typically leads to increased retail spending.","zh-TW":"高消費者信心通常會導致零售支出增加。"},{"en":"Consumer confidence fell after news of rising unemployment.","zh-TW":"失業率上升的消息傳出後，消費者信心下降了。"}]', NULL, NULL, 5, 1469, NULL),
(1470, 'consumer goods', '/kənˈsjuːmər ɡʊdz/', 'noun', '{"zh-TW":["消費品"],"en":["products purchased by individuals for personal use rather than for resale"]}', NULL, 'manufacture consumer goods / consumer goods market', '[{"en":"The consumer goods sector was resilient despite the economic slowdown.","zh-TW":"儘管經濟放緩，消費品行業仍然保持韌性。"},{"en":"Branded consumer goods command a premium over generic alternatives.","zh-TW":"品牌消費品比非品牌替代品有溢價。"}]', NULL, NULL, 5, 1470, NULL),
(1471, 'consumer surplus', '/kənˈsjuːmər ˈsɜːpləs/', 'noun', '{"zh-TW":["消費者剩餘"],"en":["the benefit consumers receive when they pay less than their maximum willingness to pay"]}', NULL, 'generate consumer surplus / calculate consumer surplus / increase consumer surplus', '[{"en":"Lower prices increase consumer surplus by allowing buyers to keep more money.","zh-TW":"較低的價格通過讓買家保留更多資金來增加消費者剩餘。"},{"en":"A price ceiling can increase consumer surplus but may cause shortages.","zh-TW":"價格上限可以增加消費者剩餘，但可能導致短缺。"}]', NULL, NULL, 5, 1471, NULL),
(1472, 'contact', '/ˈkɒntækt/', 'noun', '{"zh-TW":["聯繫；接觸","聯絡人"],"en":["communication with someone","a person who may be consulted"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tact","meaning":"touch (觸碰)"},"logic":"一起觸碰，即「聯繫」。"}', 'contact information / make contact / point of contact', '[{"en":"Please don''t hesitate to contact us for more details.","zh-TW":"如需更多詳情，請隨時與我們聯繫。"},{"en":"She is our primary point of contact for the project.","zh-TW":"她是我們這個專案的主要聯絡人。"}]', NULL, NULL, 3, 1472, 18),
(1473, 'contain', '/kənˈteɪn/', 'verb', '{"zh-TW":["包含；容納","控制"],"en":["to have within itself","to prevent from spreading","to have something inside"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tain","meaning":"hold (持有)"},"logic":"一起持有在內，即「包含」。"}', 'contain information / contain costs; contain information / self-contained', '[{"en":"The package contains fragile items.","zh-TW":"包裹內含易碎物品。"},{"en":"We must contain costs to maintain profitability.","zh-TW":"我們必須控制成本以維持獲利。"},{"en":"This box contains old photos.","zh-TW":"這個盒子裡有舊照片。"},{"en":"The drink contains no sugar.","zh-TW":"這飲料不含糖。"}]', '{"noun":"container","noun2":"content"}', NULL, 3, 1473, 307),
(1474, 'container', '/kənˈteɪnər/', 'noun', '{"zh-TW":["貨櫃；容器"],"en":["a large metal box for transporting goods by ship or truck"]}', NULL, 'shipping container / container ship', '[{"en":"The goods were packed into a 40-foot shipping container.","zh-TW":"貨物被裝入一個40英尺的貨運貨櫃中。"},{"en":"Container shipping is the backbone of international trade.","zh-TW":"貨櫃運輸是國際貿易的支柱。"}]', NULL, NULL, 3, 1474, NULL),
(1475, 'container ship', '/''kənˌteɪnər ʃɪp/', 'noun', '{"zh-TW":["貨櫃船；集裝箱船"],"en":["a large ocean-going vessel designed to carry standardized cargo containers"]}', NULL, 'charter a container ship / container ship capacity / container ship route', '[{"en":"The container ship carried over fifteen thousand containers across the Pacific.","zh-TW":"這艘貨櫃船在太平洋上運輸了超過一萬五千個貨櫃。"},{"en":"Delays at ports caused a backlog of container ships waiting to unload.","zh-TW":"港口延誤導致等待卸貨的貨櫃船積壓。"}]', NULL, NULL, 5, 1475, NULL),
(1476, 'containerization', '/kənˌteɪnərɪˈzeɪʃən/', 'noun', '{"zh-TW":["容器化"],"en":["the process of packaging software code with dependencies into isolated containers"]}', NULL, 'software containerization / containerization platform / containerization strategy', '[{"en":"Containerization enables consistent deployment across different environments.","zh-TW":"容器化允許在不同環境中進行一致的部署。"},{"en":"Docker popularized containerization by making it accessible to developers.","zh-TW":"Docker通過使容器化對開發者可及而使其普及。"}]', '{"verb":"containerize","adjective":"containerized"}', NULL, 5, 1476, NULL),
(1477, 'contamination', '/kənˌtæmɪˈneɪʃən/', 'noun', '{"zh-TW":["污染；污染物"],"en":["the presence of a harmful substance in an environment"]}', NULL, 'water contamination / soil contamination', '[{"en":"Water contamination from industrial waste is a serious problem.","zh-TW":"工業廢水污染是一個嚴重問題。"},{"en":"The contamination was detected early enough to prevent harm.","zh-TW":"污染被及時發現，避免了傷害。"}]', '{"verb":"contaminate","adjective":"contaminated"}', NULL, 5, 1477, NULL),
(1478, 'contemporaneous', '/kənˌtempəˈreɪniəs/', 'adjective', '{"zh-TW":["同時代的；同時期的"],"en":["existing or occurring at the same time"]}', NULL, 'contemporaneous evidence / contemporaneous document / contemporaneous events', '[{"en":"The contemporaneous records confirm the timeline of events.","zh-TW":"同時期的記錄確認了事件的時間線。"},{"en":"Two contemporaneous civilizations developed similar writing systems independently.","zh-TW":"兩個同時代的文明獨立發展出了類似的書寫系統。"}]', '{"adverb":"contemporaneously","noun":"contemporaneity"}', NULL, 5, 1478, NULL),
(1479, 'contemporary', '/kənˈtempərəri/', 'adjective', '{"zh-TW":["當代的；同時期的"],"en":["living or occurring at the same time","modern or current","belonging to the present time"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tempor","meaning":"time (時間)"},"suffix":{"text":"-ary","meaning":"relating to (有關的)"},"logic":"在同一時間的，即「當代的」。"}', 'contemporary art/design/issues; contemporary art / contemporary music', '[{"en":"The office features contemporary design elements.","zh-TW":"辦公室採用當代設計元素。"},{"en":"We must address contemporary business challenges.","zh-TW":"我們必須面對當代商業挑戰。"},{"en":"The gallery specializes in contemporary art.","zh-TW":"這家畫廊專營當代藝術。"},{"en":"She is one of the greatest contemporary writers.","zh-TW":"她是最偉大的當代作家之一。"}]', '{"noun":"contemporary"}', NULL, 4, 1479, NULL),
(1480, 'contend', '/''kənˌtend/', 'verb', '{"zh-TW":["競爭；主張；應付"],"en":["to struggle to surmount a difficulty; to assert something as a position in an argument"]}', NULL, 'contend with / contend for / contend that', '[{"en":"Athletes must contend with both physical and psychological challenges during competition.","zh-TW":"運動員在比賽期間必須應付身體和心理上的挑戰。"},{"en":"The lawyer contended that the evidence was obtained illegally.","zh-TW":"律師主張證據是非法獲得的。"}]', '{"noun":"contender","noun2":"contention","adjective":"contentious"}', NULL, 3, 1480, NULL),
(1481, 'content', '/ˈkɒntent/', 'noun', '{"zh-TW":["內容；目錄"],"en":["the material dealt with in a speech, text, or work"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tent","meaning":"hold (持有)"},"logic":"被一起持有在內的，即「內容」。"}', 'content marketing / table of contents / digital content', '[{"en":"The website needs fresh content updated weekly.","zh-TW":"網站需要每週更新新鮮內容。"},{"en":"Refer to the table of contents for guidance.","zh-TW":"請參閱目錄以獲取指導。"}]', NULL, NULL, 3, 1481, 308),
(1482, 'content marketing', '/ˈkɒntent ˈmɑːrkɪtɪŋ/', 'noun', '{"zh-TW":["內容行銷"],"en":["creating and sharing valuable content to attract and engage customers"]}', NULL, 'content marketing strategy / content marketing plan / B2B content marketing', '[{"en":"Content marketing builds trust and generates organic traffic.","zh-TW":"內容行銷建立信任並產生自然流量。"},{"en":"The blog is the centerpiece of their content marketing strategy.","zh-TW":"部落格是他們內容行銷策略的核心。"}]', '{"noun":"content marketer"}', NULL, 5, 1482, NULL),
(1483, 'contentious', '/kənˈtenʃəs/', 'adjective', '{"zh-TW":["有爭議的；爭論性的"],"en":["causing or likely to cause argument or controversy"]}', NULL, 'contentious issue / contentious debate / contentious claim', '[{"en":"The proposed budget cuts remain one of the most contentious issues.","zh-TW":"擬議的預算削減仍是最具爭議的問題之一。"},{"en":"Her contentious remarks sparked a heated public debate.","zh-TW":"她有爭議的言論引發了激烈的公眾辯論。"}]', '{"adverb":"contentiously","noun":"contentiousness"}', NULL, 4, 1483, NULL),
(1484, 'contest', '/ˈkɒntest/', 'noun', '{"zh-TW":["比賽；競爭","質疑"],"en":["a competition","to dispute or challenge"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"test","meaning":"witness (見證)"},"logic":"一起見證對決，即「比賽」。"}', 'contest a claim / enter a contest', '[{"en":"The company decided to contest the lawsuit.","zh-TW":"公司決定對訴訟進行抗辯。"},{"en":"Employees can enter the innovation contest.","zh-TW":"員工可以參加創新比賽。"}]', '{"noun":"contestant"}', NULL, 3, 1484, NULL),
(1485, 'contestant', '/kənˈtɛstənt/', 'noun', '{"zh-TW":["參賽者"],"en":["a person who takes part in a competition"]}', NULL, 'reality show contestant / elimination of contestants', '[{"en":"The contestant answered correctly.","zh-TW":"參賽者答對了。"},{"en":"Fifty contestants entered the competition.","zh-TW":"五十位參賽者參加了比賽。"}]', '{"noun2":"contest"}', NULL, 4, 1485, NULL),
(1486, 'contestation', '/ˌkɒntesˈteɪʃən/', 'noun', '{"zh-TW":["爭辯；異議；競爭"],"en":["the action or process of disputing something or competing for something"]}', NULL, 'political contestation / social contestation / open contestation', '[{"en":"The election results were met with widespread contestation in the courts.","zh-TW":"選舉結果在法庭上遭到廣泛異議。"},{"en":"Academic theories are subject to ongoing contestation and revision.","zh-TW":"學術理論受到持續的爭辯和修正。"}]', '{"verb":"contest","adjective":"contested"}', NULL, 4, 1486, NULL),
(1487, 'context', '/ˈkɒntekst/', 'noun', '{"zh-TW":["背景；上下文"],"en":["the circumstances that form the setting for an event"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"text","meaning":"weave (編織)"},"logic":"一起編織的環境，即「背景」。"}', 'in context / business context / cultural context', '[{"en":"The remarks must be understood in context.","zh-TW":"這些言論必須在上下文中理解。"},{"en":"In a business context, this term has a specific meaning.","zh-TW":"在商業背景下，這個術語有特定含義。"}]', '{"adjective":"contextual"}', NULL, 3, 1487, NULL),
(1488, 'contextualize', '/kənˈtekstʃuəlaɪz/', 'verb', '{"zh-TW":["將…置於背景中；脈絡化"],"en":["to place something in its proper context for better understanding"]}', NULL, 'contextualize data / contextualize findings / contextualize the research', '[{"en":"Always contextualize your data within the broader literature.","zh-TW":"始終將數據置於更廣泛的文獻背景中。"},{"en":"The article contextualizes the policy changes within historical trends.","zh-TW":"文章將政策變化置於歷史趨勢的脈絡中。"}]', '{"noun":"contextualization","adjective":"contextualized"}', NULL, 5, 1488, NULL),
(1489, 'continental breakfast', '/ˌkɒntɪˌnɛntəl ˈbrɛkfəst/', 'noun', '{"zh-TW":["歐式早餐"],"en":["a light breakfast of bread, pastries, and coffee"]}', NULL, 'enjoy a continental breakfast / continental breakfast included', '[{"en":"A continental breakfast is served from 7 to 10 am.","zh-TW":"歐式早餐從早上7點供應至10點。"},{"en":"The rate includes a daily continental breakfast.","zh-TW":"房價包含每日歐式早餐。"}]', NULL, NULL, 5, 1489, NULL),
(1490, 'contingency', '/kənˈtɪndʒənsi/', 'noun', '{"zh-TW":["應急措施；意外事件"],"en":["a future event that is possible but cannot be predicted","a possible future event that must be prepared for"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"ting","meaning":"touch (觸碰)"},"suffix":{"text":"-ency","meaning":"state (狀態)"},"logic":"可能觸碰到的事件狀態，即「意外事件」。"}', 'contingency plan / contingency fund', '[{"en":"We need a contingency plan in case of delays.","zh-TW":"我們需要一個應對延遲的應急計畫。"},{"en":"The budget includes a 10% contingency fund.","zh-TW":"預算包含10%的應急基金。"},{"en":"We need a contingency plan for supply disruptions.","zh-TW":"我們需要一個應對供應中斷的應急計畫。"},{"en":"Set aside a contingency fund.","zh-TW":"設置一筆應急基金。"}]', '{"adjective":"contingent","noun":"contingency"}', NULL, 4, 1490, 764),
(1491, 'contingency fund', '/kənˈtɪndʒənsi fʌnd/', 'noun', '{"zh-TW":["應急資金；預備基金"],"en":["money set aside to cover unexpected expenses or emergencies"]}', NULL, 'establish a contingency fund / draw from the contingency fund', '[{"en":"A contingency fund of 10% was included in the project budget.","zh-TW":"項目預算中包含了10%的應急資金。"},{"en":"The contingency fund covered the unexpected equipment failure costs.","zh-TW":"應急資金涵蓋了意外設備故障的費用。"}]', NULL, NULL, 5, 1491, NULL),
(1492, 'contingency plan', '/kənˈtɪndʒənsi plæn/', 'noun', '{"zh-TW":["應急計劃；緊急預案"],"en":["a plan prepared for unforeseen events"]}', NULL, 'develop a contingency plan / activate a contingency plan', '[{"en":"A contingency plan was prepared in case of supply chain disruption.","zh-TW":"準備了應急計劃以防止供應鏈中斷。"},{"en":"Activating the contingency plan helped minimize disruption.","zh-TW":"啟動應急計劃幫助將中斷降到最低。"}]', NULL, NULL, 5, 1492, NULL),
(1493, 'contingency reserve', '/kənˈtɪndʒənsi rɪˈzɜːrv/', 'noun', '{"zh-TW":["應急儲備金"],"en":["funds set aside to cover unexpected project expenses"]}', NULL, 'set up a contingency reserve / draw on the contingency reserve', '[{"en":"A 10% contingency reserve was included in the project budget.","zh-TW":"項目預算中包含了10%的應急儲備金。"},{"en":"The team drew on the contingency reserve to cover unexpected costs.","zh-TW":"團隊動用了應急儲備金來支付意外費用。"}]', NULL, NULL, 5, 1493, NULL),
(1494, 'contingent', '/kənˈtɪndʒənt/', 'adjective', '{"zh-TW":["取決於；視情況而定的"],"en":["subject to chance; dependent on circumstances"]}', NULL, 'contingent on results / contingent liability / contingent outcome', '[{"en":"The funding is contingent on meeting the performance benchmarks.","zh-TW":"資金取決於是否達到績效基準。"},{"en":"The plan is contingent on regulatory approval being granted.","zh-TW":"計畫取決於是否獲得監管批准。"}]', '{"noun":"contingency","adverb":"contingently"}', NULL, 4, 1494, NULL),
(1495, 'contingent liability', '/kənˈtɪndʒənt laɪəˈbɪlɪti/', 'noun', '{"zh-TW":["或有負債；潛在負債"],"en":["a potential obligation that may arise depending on the outcome of an uncertain event"]}', NULL, 'disclose contingent liabilities / contingent liability disclosure', '[{"en":"The company disclosed a contingent liability for the ongoing lawsuit.","zh-TW":"公司披露了正在進行的訴訟的或有負債。"},{"en":"Contingent liabilities are noted in the financial statement footnotes.","zh-TW":"或有負債在財務報表附注中說明。"}]', NULL, NULL, 5, 1495, NULL),
(1496, 'continue', '/kənˈtɪnjuː/', 'verb', '{"zh-TW":["繼續"],"en":["to keep going; not stop","to keep doing something without stopping"]}', NULL, 'continue to grow / continue with; continue to / continue with', '[{"en":"Sales continue to grow each quarter.","zh-TW":"銷售額每季持續成長。"},{"en":"Let''s continue with the presentation.","zh-TW":"讓我們繼續報告。"},{"en":"Please continue reading.","zh-TW":"請繼續閱讀。"},{"en":"The rain continued all day.","zh-TW":"雨下了一整天。"}]', '{"verb":"continue","adjective":"continuous","adverb":"continuously","noun":"continuation"}', NULL, 3, 1496, 309),
(1497, 'continuing education', '/''kɒntɪnjuɪŋ ˌedʒʊˈkeɪʃən/', 'noun', '{"zh-TW":["繼續教育；終身學習"],"en":["the ongoing education of adult learners, particularly those engaged in professional work"]}', NULL, 'enroll in continuing education / continuing education program / benefits of continuing education', '[{"en":"Many professionals take continuing education courses to stay current in their fields.","zh-TW":"許多專業人士參加繼續教育課程，以保持在其領域的最新知識。"},{"en":"The company reimburses employees for continuing education expenses up to a set limit.","zh-TW":"公司為員工報銷繼續教育費用，最高可達規定限額。"}]', NULL, NULL, 5, 1497, NULL),
(1498, 'continuous improvement', '/kənˈtɪnjuəs ɪmˈpruːvmənt/', 'noun', '{"zh-TW":["持續改善"],"en":["an ongoing process of identifying and implementing incremental improvements"]}', NULL, 'implement continuous improvement / culture of continuous improvement', '[{"en":"A culture of continuous improvement drives long-term competitiveness.","zh-TW":"持續改善的文化推動了長期競爭力。"},{"en":"The manufacturing team uses Kaizen for continuous improvement.","zh-TW":"製造團隊使用改善（Kaizen）進行持續改善。"}]', NULL, NULL, 5, 1498, NULL),
(1499, 'continuous integration', '/kənˈtɪnjuəs ˌɪntɪˈɡreɪʃən/', 'noun', '{"zh-TW":["持續整合"],"en":["the practice of automatically merging and testing code changes frequently"]}', NULL, 'implement continuous integration / continuous integration pipeline / continuous integration tool', '[{"en":"Continuous integration detects integration errors early in development.","zh-TW":"持續整合在開發早期檢測整合錯誤。"},{"en":"The team set up a continuous integration pipeline to automate testing.","zh-TW":"團隊建立了持續整合管道以自動化測試。"}]', NULL, NULL, 5, 1499, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1500, 'contract', '/ˈkɒntrækt/', 'noun', '{"zh-TW":["合約；契約"],"en":["a written or spoken agreement that is legally binding"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tract","meaning":"draw (拉)"},"logic":"一起拉在一起的約定，即「合約」。"}', 'sign a contract / breach of contract / contract terms', '[{"en":"Both parties signed the contract last week.","zh-TW":"雙方上週簽署了合約。"},{"en":"The contract expires at the end of this year.","zh-TW":"合約於今年年底到期。"}]', '{"noun":"contractor","adjective":"contractual"}', NULL, 3, 1500, 19),
(1501, 'contract administration', '/ˈkɒntrækt ədˌmɪnɪˈstreɪʃən/', 'noun', '{"zh-TW":["合約管理"],"en":["the management of a contract from execution to completion"]}', NULL, 'handle contract administration / contract administration team', '[{"en":"Effective contract administration reduces disputes and cost overruns.","zh-TW":"有效的合約管理減少了爭議和成本超支。"},{"en":"Contract administration involves tracking milestones, changes, and payments.","zh-TW":"合約管理涉及追蹤里程碑、變更和付款。"}]', NULL, NULL, 5, 1501, NULL),
(1502, 'contract employee', '/ˈkɒntrækt ɪmˈplɔɪiː/', 'noun', '{"zh-TW":["約聘員工；合約員工"],"en":["an employee hired for a fixed term or project"]}', NULL, 'hire a contract employee / contract employee agreement', '[{"en":"The company hired contract employees for the seasonal workload.","zh-TW":"公司為季節性工作量聘用了約聘員工。"},{"en":"Contract employees are not entitled to the same benefits as permanent staff.","zh-TW":"約聘員工無權享受與正式員工相同的福利。"}]', NULL, NULL, 5, 1502, NULL),
(1503, 'contract management', '/ˈkɒntrækt ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["合約管理"],"en":["the process of managing contracts with vendors, partners, and customers"]}', NULL, 'contract management system / effective contract management', '[{"en":"Contract management software automates renewal reminders.","zh-TW":"合約管理軟體自動提醒續約。"},{"en":"Poor contract management can lead to missed obligations.","zh-TW":"糟糕的合約管理可能導致錯過義務。"}]', '{"noun":"contract manager"}', NULL, 5, 1503, NULL),
(1504, 'contract negotiation', '/ˈkɒntrækt nɪˌɡoʊʃiˈeɪʃən/', 'noun', '{"zh-TW":["合約談判"],"en":["the process of discussing and agreeing on terms of a contract between parties"]}', NULL, 'conduct contract negotiations / contract negotiation strategy', '[{"en":"Contract negotiations with the supplier lasted three months.","zh-TW":"與供應商的合約談判持續了三個月。"},{"en":"Experienced legal counsel improves outcomes in complex contract negotiations.","zh-TW":"有經驗的法律顧問改善了複雜合約談判的結果。"}]', NULL, NULL, 5, 1504, NULL),
(1505, 'contract renewal', '/ˈkɒntrækt rɪˈnjuːəl/', 'noun', '{"zh-TW":["合約續簽；合約更新"],"en":["the extension or re-signing of an existing contract"]}', NULL, 'negotiate a contract renewal / contract renewal date', '[{"en":"The contract renewal was negotiated two months before expiry.","zh-TW":"合約續簽在到期前兩個月進行了談判。"},{"en":"Clients receive a reminder 30 days before contract renewal.","zh-TW":"顧客在合約續簽前30天收到提醒。"}]', NULL, NULL, 5, 1505, NULL),
(1506, 'contraction', '/kənˈtrækʃən/', 'noun', '{"zh-TW":["收縮；衰退；縮減"],"en":["a reduction in economic activity; the process of becoming smaller"]}', NULL, 'economic contraction / credit contraction / period of contraction', '[{"en":"The economy entered a contraction after two consecutive quarters of negative growth.","zh-TW":"在連續兩個季度負增長後，經濟進入了收縮。"},{"en":"A contraction in consumer spending signals weakening business confidence.","zh-TW":"消費者支出的收縮預示著商業信心的減弱。"}]', '{"verb":"contract","adjective":"contractionary"}', NULL, 4, 1506, NULL),
(1507, 'contractor', 'ˈkɒntræktər', 'noun', '{"zh-TW":["承包商；合約工","包商"],"en":["a person hired on contract","a company hired for specific work"]}', NULL, 'hire a contractor/independent contractor', '[{"en":"We work with specialized contractors.","zh-TW":"我們與專業承包商合作。"}]', '{"noun":"contract","adjective":"contracted"}', NULL, 4, 1507, 310),
(1508, 'contractual obligation', '/kənˈtræktʃuəl ˌɒblɪˈɡeɪʃən/', 'noun', '{"zh-TW":["合約義務"],"en":["a duty that arises from and is enforceable through a legally binding contract"]}', NULL, 'fulfill contractual obligations / breach a contractual obligation', '[{"en":"The supplier met all its contractual obligations on time.","zh-TW":"供應商按時履行了所有合約義務。"},{"en":"Failure to meet contractual obligations may result in damages.","zh-TW":"未能履行合約義務可能導致賠償。"}]', NULL, NULL, 5, 1508, NULL),
(1509, 'contraindication', '/ˌkɒntrəˌɪndɪˈkeɪʃən/', 'noun', '{"zh-TW":["禁忌症"],"en":["a condition that makes a particular treatment inadvisable"]}', NULL, 'identify contraindications / absolute contraindication / relative contraindication', '[{"en":"Pregnancy is a contraindication for many powerful medications.","zh-TW":"懷孕是許多強效藥物的禁忌症。"},{"en":"The physician checked for contraindications before prescribing.","zh-TW":"醫師在開處方前檢查了禁忌症。"}]', '{"verb":"contraindicate","adjective":"contraindicated"}', NULL, 5, 1509, NULL),
(1510, 'contribute', '/kənˈtrɪbjuːt/', 'verb', '{"zh-TW":["貢獻；捐助"],"en":["to give something to help achieve a common goal"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tribute","meaning":"give (給予)"},"logic":"一起給予，即「貢獻」。"}', 'contribute to / contribute funds/ideas', '[{"en":"Each team member contributed ideas to the project.","zh-TW":"每位團隊成員都為專案貢獻了想法。"},{"en":"Tourism contributes significantly to the local economy.","zh-TW":"旅遊業對當地經濟有重大貢獻。"}]', '{"noun":"contribution","noun2":"contributor"}', NULL, 4, 1510, 92),
(1511, 'contribution', 'ˌkɒntrɪˈbjuːʃən', 'noun', '{"zh-TW":["貢獻；捐助","投入"],"en":["something given to help","a donation or effort"]}', NULL, 'valuable contribution/financial contribution', '[{"en":"Thank you for your valuable contributions.","zh-TW":"感謝您寶貴的貢獻。"}]', '{"verb":"contribute","adjective":"contributing"}', NULL, 4, 1511, 532),
(1512, 'contribution margin', '/ˌkɒntrɪˈbjuːʃən ˈmɑːrdʒɪn/', 'noun', '{"zh-TW":["貢獻毛利；邊際貢獻"],"en":["the amount by which a product''s revenue exceeds its variable costs"]}', NULL, 'calculate contribution margin / improve contribution margin', '[{"en":"The contribution margin analysis showed which products were most profitable.","zh-TW":"貢獻毛利分析顯示了哪些產品最有利可圖。"},{"en":"A high contribution margin means more revenue is available for fixed costs.","zh-TW":"高貢獻毛利意味著有更多收入可用於覆蓋固定成本。"}]', NULL, NULL, 5, 1512, NULL),
(1513, 'control', '/kənˈtroʊl/', 'noun', '{"zh-TW":["控制；管理"],"en":["the power to direct","to manage or regulate"]}', NULL, 'quality control / under control', '[{"en":"Quality control is essential in manufacturing.","zh-TW":"品質管理在製造業中至關重要。"},{"en":"The situation is under control.","zh-TW":"情況在掌控之中。"}]', '{"noun":"control","verb":"control","adjective":"controllable","noun2":"controller"}', NULL, 3, 1513, NULL),
(1514, 'control environment', '/kənˈtroʊl ɪnˈvaɪrənmənt/', 'noun', '{"zh-TW":["控制環境"],"en":["the overall culture and structure supporting effective internal controls"]}', NULL, 'assess control environment / strengthen control environment', '[{"en":"A strong control environment reduces the risk of fraud.","zh-TW":"強大的控制環境降低了欺詐風險。"},{"en":"The audit highlighted weaknesses in the control environment.","zh-TW":"審計指出了控制環境中的薄弱環節。"}]', NULL, NULL, 5, 1514, NULL),
(1515, 'controller', '/kənˈtroʊlər/', 'noun', '{"zh-TW":["財務總監；主計長"],"en":["the chief accounting officer responsible for financial reporting"]}', NULL, 'financial controller / appoint a controller / role of controller', '[{"en":"The controller oversees the company''s financial reporting process.","zh-TW":"財務總監監督公司的財務報告流程。"},{"en":"She was promoted to controller after ten years in the finance department.","zh-TW":"她在財務部門工作了十年後晉升為財務總監。"}]', '{"plural":"controllers"}', NULL, 4, 1515, NULL),
(1516, 'controversial', '/ˌkɒntrəˈvɜːrʃl/', 'adjective', '{"zh-TW":["有爭議的"],"en":["causing disagreement or discussion"]}', '{"prefix":{"text":"contra-","meaning":"against (對立)"},"root":{"text":"vers","meaning":"turn (轉向)"},"suffix":{"text":"-ial","meaning":"relating to (有關的)"},"logic":"朝對立方向轉的，即「有爭議的」。"}', 'controversial decision/issue/topic', '[{"en":"The board made a controversial decision to outsource.","zh-TW":"董事會做出了有爭議的外包決定。"},{"en":"The policy remains highly controversial.","zh-TW":"該政策仍然極具爭議。"}]', '{"noun":"controversy"}', NULL, 5, 1516, NULL),
(1517, 'controversy', '/ˈkɒntrəvɜːrsi/', 'noun', '{"zh-TW":["爭議"],"en":["prolonged public disagreement"]}', '{"prefix":{"text":"contra-","meaning":"against (反對)"},"root":{"text":"vers","meaning":"turn (轉)"},"suffix":{"text":"-y","meaning":"state (狀態)"},"logic":"反向轉動的狀態，即「爭議」。"}', 'cause controversy / political controversy', '[{"en":"The decision caused a lot of controversy.","zh-TW":"這個決定引起了很多爭議。"},{"en":"The new law has been surrounded by controversy.","zh-TW":"新法律一直充滿爭議。"}]', '{"adjective":"controversial"}', NULL, 4, 1517, NULL),
(1518, 'convene', '/kənˈviːn/', 'verb', '{"zh-TW":["召集；集合"],"en":["to bring together or call a meeting of a group"]}', NULL, 'convene a meeting / convene a committee', '[{"en":"The board will convene an emergency meeting to address the crisis.","zh-TW":"董事會將召集緊急會議應對危機。"},{"en":"The annual summit convened experts from 30 countries.","zh-TW":"年度峰會召集了來自30個國家的專家。"}]', '{"noun":"convention","adjective":"convened"}', NULL, 3, 1518, 661),
(1519, 'convenience', 'kənˈviːniəns', 'noun', '{"zh-TW":["方便；便利","舒適"],"en":["being easy to do or reach","a time that suits you"]}', NULL, 'at your convenience/for convenience', '[{"en":"Please call at your convenience.","zh-TW":"請在您方便的時候致電。"}]', '{"adjective":"convenient","adverb":"conveniently"}', NULL, 4, 1519, NULL),
(1520, 'convenience store', '/kənˈviːniəns stɔːr/', 'noun', '{"zh-TW":["便利店；便利商店"],"en":["a small retail outlet offering basic goods with extended hours"]}', NULL, 'operate a convenience store / convenience store chain', '[{"en":"The convenience store chain expanded to 1000 locations nationally.","zh-TW":"便利店連鎖擴展到了全國1000個地點。"},{"en":"Convenience stores generate high revenue per square meter.","zh-TW":"便利店每平方米產生的收入很高。"}]', NULL, NULL, 5, 1520, NULL),
(1521, 'convenient', '/kənˈviːniənt/', 'adjective', '{"zh-TW":["方便的；便利的"],"en":["fitting in well with needs or plans; easy to use"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"ven","meaning":"come (來)"},"suffix":{"text":"-ient","meaning":"being (存在的)"},"logic":"一起來到適合的地方，即「方便的」。"}', 'convenient location/time / at your convenience', '[{"en":"Please call us at your earliest convenience.","zh-TW":"請在您方便時盡早致電。"},{"en":"The office is in a convenient downtown location.","zh-TW":"辦公室位於便利的市中心位置。"}]', '{"noun":"convenience","adverb":"conveniently"}', NULL, 4, 1521, 20),
(1522, 'convention', '/kənˈvenʃn/', 'noun', '{"zh-TW":["大會；慣例"],"en":["a large meeting or conference","a widely accepted practice"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"ven","meaning":"come (來)"},"suffix":{"text":"-tion","meaning":"action (動作)"},"logic":"一起來的行動，即「大會」。"}', 'convention center / industry convention / by convention', '[{"en":"The annual convention attracted 3,000 attendees.","zh-TW":"年度大會吸引了3,000位出席者。"},{"en":"By convention, the report is submitted quarterly.","zh-TW":"按照慣例，報告每季提交。"}]', '{"adjective":"conventional"}', NULL, 4, 1522, 533),
(1523, 'convergence', '/kənˈvɜːrdʒəns/', 'noun', '{"zh-TW":["收斂；趨同"],"en":["the process of coming together from different directions"]}', NULL, 'technological convergence / policy convergence / economic convergence', '[{"en":"Technological convergence is blending previously separate industries.","zh-TW":"技術融合正在將以前獨立的行業融合在一起。"},{"en":"Economic convergence between rich and poor regions is a policy goal.","zh-TW":"富裕地區和貧困地區之間的經濟趨同是一個政策目標。"}]', '{"verb":"converge","adjective":"convergent"}', NULL, 4, 1523, NULL),
(1524, 'conversation', '/ˌkɒnvərˈseɪʃən/', 'noun', '{"zh-TW":["對話；交談"],"en":["a talk between two or more people"]}', NULL, 'have a conversation / casual conversation', '[{"en":"We had a long conversation.","zh-TW":"我們進行了一場長談。"},{"en":"I overheard their conversation.","zh-TW":"我無意間聽到了他們的對話。"}]', '{"verb":"converse","adjective":"conversational"}', NULL, 4, 1524, NULL),
(1525, 'conversion rate', '/kənˈvɜːrʒən reɪt/', 'noun', '{"zh-TW":["轉換率"],"en":["the percentage of visitors or leads that complete a desired action"]}', NULL, 'improve conversion rate / conversion rate optimization / track conversion rate', '[{"en":"The landing page redesign improved the conversion rate by 30%.","zh-TW":"登陸頁面重新設計將轉換率提高了30%。"},{"en":"A low conversion rate indicates friction in the sales process.","zh-TW":"低轉換率表示銷售流程中存在阻力。"}]', '{"abbreviation":"CVR","verb":"convert"}', NULL, 5, 1525, NULL),
(1526, 'convert', '/kənˈvɜːrt/', 'verb', '{"zh-TW":["轉換；改變"],"en":["to change from one form or use to another"]}', '{"prefix":{"text":"con-","meaning":"completely (完全)"},"root":{"text":"vert","meaning":"turn (轉)"},"logic":"完全轉變，即「轉換」。"}', 'convert currency/data/file', '[{"en":"The warehouse was converted into office space.","zh-TW":"倉庫被改建為辦公空間。"},{"en":"Please convert the amounts to US dollars.","zh-TW":"請將金額轉換為美元。"}]', '{"noun":"conversion"}', NULL, 3, 1526, 734),
(1527, 'convertible', '/kənˈvɜːrtɪbəl/', 'adjective', '{"zh-TW":["可轉換的；可換算的"],"en":["(of a financial instrument) able to be converted into shares"]}', NULL, 'convertible bond / convertible note / convertible preferred', '[{"en":"The startup issued convertible notes to bridge to its Series A round.","zh-TW":"初創公司發行可轉換票據以橋接到A輪融資。"},{"en":"Convertible bonds offer investors both income and equity upside.","zh-TW":"可轉換債券為投資者提供收益和股權上升空間。"}]', '{"noun":"convertible","verb":"convert"}', NULL, 4, 1527, NULL),
(1528, 'convertible bond', '/kənˈvɜːrtɪbəl bɒnd/', 'noun', '{"zh-TW":["可轉換債券"],"en":["a bond that can be converted into company shares at a specified price"]}', NULL, 'issue convertible bonds / invest in convertible bonds', '[{"en":"The company issued convertible bonds to raise growth capital.","zh-TW":"公司發行可轉換債券以籌集增長資本。"},{"en":"Investors prefer convertible bonds for downside protection.","zh-TW":"投資者偏好可轉換債券以獲得下行保護。"}]', NULL, NULL, 5, 1528, NULL),
