(1530, 'convertible preferred stock', '/kənˈvɜːrtɪbl prɪˈfɜːrd stɒk/', 'noun', '{"zh-TW":["可轉換優先股"],"en":["preferred shares that can be converted into common shares at the investor''s option"]}', NULL, 'issue convertible preferred stock / convertible preferred stock terms', '[{"en":"Venture investors often receive convertible preferred stock in early-stage deals.","zh-TW":"風險投資者通常在早期交易中獲得可轉換優先股。"},{"en":"Convertible preferred stock offers downside protection with equity upside.","zh-TW":"可轉換優先股提供了下行保護和股權上行潛力。"}]', NULL, NULL, 5, 1530, NULL),
(1531, 'convey', '/kənˈveɪ/', 'verb', '{"zh-TW":["傳達；運送"],"en":["to communicate a message or idea","to transport something"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"vey","meaning":"way/carry (路/攜帶)"},"logic":"一起帶走傳送，即「傳達」。"}', 'convey a message/meaning/impression', '[{"en":"The email failed to convey the urgency of the situation.","zh-TW":"電子郵件未能傳達情況的緊迫性。"},{"en":"Charts can convey complex data effectively.","zh-TW":"圖表可以有效傳達複雜數據。"}]', NULL, NULL, 2, 1531, NULL),
(1532, 'conveyance', '/kənˈveɪəns/', 'noun', '{"zh-TW":["不動產轉讓；運送"],"en":["the legal process of transferring ownership of property"]}', NULL, 'property conveyance / deed of conveyance', '[{"en":"All documents for the conveyance must be signed by both parties.","zh-TW":"不動產轉讓的所有文件必須由雙方簽署。"},{"en":"Conveyance fees are included in the total cost of purchasing property.","zh-TW":"不動產轉讓費包含在購房總費用中。"}]', '{"verb":"convey","noun":"conveyancer"}', NULL, 4, 1532, 766),
(1533, 'conveyancing', '/''kɒnˈveɪənsɪŋ/', 'noun', '{"zh-TW":["房地產轉讓手續；產權轉讓"],"en":["the legal process of transferring ownership of property from one person to another"]}', NULL, 'handle conveyancing / conveyancing lawyer / conveyancing process', '[{"en":"Buyers typically hire a solicitor to handle the conveyancing process.","zh-TW":"買家通常會聘請律師處理產權轉讓手續。"},{"en":"Conveyancing involves checking legal titles, contracts, and transferring funds.","zh-TW":"產權轉讓涉及核查法律產權、合同和資金轉移。"}]', '{"noun":"conveyancer"}', NULL, 4, 1533, NULL),
(1534, 'conviction', '/kənˈvɪkʃən/', 'noun', '{"zh-TW":["定罪；信念"],"en":["being found guilty of a crime"]}', NULL, 'criminal conviction / strong conviction', '[{"en":"He has no prior convictions.","zh-TW":"他沒有前科。"},{"en":"She spoke with strong conviction.","zh-TW":"她說話帶著堅定的信念。"}]', '{"verb":"convict"}', NULL, 4, 1534, NULL),
(1535, 'convince', '/kənˈvɪns/', 'verb', '{"zh-TW":["說服；使確信","說服"],"en":["to cause someone to believe something firmly","to make someone believe something"]}', '{"prefix":{"text":"con-","meaning":"completely (完全)"},"root":{"text":"vince","meaning":"conquer (征服)"},"logic":"完全征服某人的想法，即「說服」。"}', 'convince sb to do / convince sb that; convince someone to / hard to convince', '[{"en":"She convinced the board to approve the budget increase.","zh-TW":"她說服董事會批准增加預算。"},{"en":"The data convinced us that the strategy was working.","zh-TW":"數據使我們確信策略正在奏效。"},{"en":"She convinced me to try it.","zh-TW":"她說服我去嘗試。"},{"en":"I''m not convinced that''s the best option.","zh-TW":"我不確信那是最好的選擇。"}]', '{"adjective":"convincing"}', NULL, 3, 1535, NULL),
(1536, 'convocation', '/ˌkɒnvəˈkeɪʃən/', 'noun', '{"zh-TW":["集合；召集；畢業典禮"],"en":["a formal assembly of a university, church, or other body"]}', NULL, 'attend convocation / university convocation / convocation ceremony', '[{"en":"The university held its annual convocation to award degrees to graduating students.","zh-TW":"大學舉行了年度畢業典禮，向畢業生頒發學位。"},{"en":"The convocation of parliament was delayed due to the political crisis.","zh-TW":"由於政治危機，議會的召集被推遲了。"}]', '{"verb":"convoke"}', NULL, 4, 1536, NULL),
(1537, 'COO', '/ˌsiː oʊ ˈoʊ/', 'noun', '{"zh-TW":["營運長；首席營運官"],"en":["chief operating officer; the executive managing daily operations"]}', NULL, 'COO responsibilities / appoint a COO', '[{"en":"The COO is responsible for supply chain and production operations.","zh-TW":"營運長負責供應鏈和生產運營。"},{"en":"She was promoted to COO after successfully launching three products.","zh-TW":"她在成功推出三款產品後晉升為營運長。"}]', '{"full form":"chief operating officer"}', NULL, 1, 1537, NULL),
(1538, 'cook', '/kʊk/', 'verb', '{"zh-TW":["烹飪；廚師","烹飪；做飯"],"en":["to prepare food by heating","a person who cooks"]}', NULL, 'cook a meal / head cook; cook dinner / cook up', '[{"en":"She cooks dinner every evening.","zh-TW":"她每天晚上煮晚餐。"},{"en":"The restaurant hired a new head cook.","zh-TW":"餐廳聘請了一位新主廚。"},{"en":"Who''s cooking dinner tonight?","zh-TW":"今晚誰做飯？"},{"en":"She cooks really well.","zh-TW":"她做飯很好吃。"}]', '{"verb":"cook","noun":"cook","noun2":"cooking","noun3":"cooker"}', NULL, 1, 1538, NULL),
(1539, 'cookie', '/ˈkʊki/', 'noun', '{"zh-TW":["餅乾"],"en":["a small flat sweet cake"]}', NULL, 'chocolate chip cookie / cookie jar', '[{"en":"Would you like a cookie?","zh-TW":"你想要一塊餅乾嗎？"},{"en":"She baked cookies for the party.","zh-TW":"她為派對烤了餅乾。"}]', NULL, NULL, 2, 1539, NULL),
(1540, 'cool', '/kuːl/', 'adjective', '{"zh-TW":["涼爽的；冷靜的","涼的；酷的"],"en":["slightly cold","calm and relaxed","slightly cold; fashionable"]}', NULL, 'keep cool / cool down; cool down / keep cool', '[{"en":"Keep cool under pressure.","zh-TW":"在壓力下保持冷靜。"},{"en":"The weather is getting cooler.","zh-TW":"天氣變得越來越涼爽。"},{"en":"The weather is getting cool.","zh-TW":"天氣漸漸涼了。"},{"en":"That''s a really cool jacket.","zh-TW":"那件夾克真酷。"}]', '{"adjective":"cool","verb":"cool","noun":"coolness","adverb":"coolly"}', NULL, 1, 1540, NULL),
(1541, 'cool-down', '/''kuːl daʊn/', 'noun', '{"zh-TW":["緩和運動；收操"],"en":["a period of gentle exercise done after more intense physical activity to gradually return to a resting state"]}', NULL, 'do a cool-down / proper cool-down / post-workout cool-down', '[{"en":"Always follow intense exercise with a cool-down to prevent muscle soreness.","zh-TW":"劇烈運動後始終要做緩和運動，以防止肌肉酸痛。"},{"en":"A five-minute cool-down helps reduce heart rate gradually after exercise.","zh-TW":"五分鐘的緩和運動有助於在運動後逐漸降低心率。"}]', NULL, NULL, 3, 1541, NULL),
(1542, 'cooperate', '/kəʊˈɒpəreɪt/', 'verb', '{"zh-TW":["合作；配合","合作"],"en":["to work together toward a common goal"]}', '{"prefix":{"text":"co-","meaning":"together (一起)"},"root":{"text":"oper","meaning":"work (工作)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"一起工作，即「合作」。"}', 'cooperate with / cooperate closely; cooperate with / cooperate fully', '[{"en":"Both departments must cooperate to meet the deadline.","zh-TW":"兩個部門必須合作以趕上截止日期。"},{"en":"The company cooperated fully with the investigation.","zh-TW":"公司全力配合調查。"},{"en":"The two companies agreed to cooperate on the project.","zh-TW":"兩家公司同意在該專案上合作。"},{"en":"Please cooperate with the investigation.","zh-TW":"請配合調查。"}]', '{"noun":"cooperation","adjective":"cooperative"}', NULL, 3, 1542, NULL),
(1543, 'cooperation', 'koʊˌɒpəˈreɪʃən', 'noun', '{"zh-TW":["合作；協作","配合"],"en":["working together toward a goal","joint effort"]}', NULL, 'international cooperation/close cooperation', '[{"en":"Thank you for your cooperation.","zh-TW":"感謝您的合作。"}]', '{"verb":"cooperate","adjective":"cooperative","adverb":"cooperatively"}', NULL, 4, 1543, 311),
(1544, 'cooperative', '/koʊˈɒpərətɪv/', 'noun', '{"zh-TW":["合作社；合作企業"],"en":["a business owned and operated collectively by its members for shared benefit"]}', NULL, 'form a cooperative / cooperative member', '[{"en":"The farmers formed a cooperative to negotiate better prices for their produce.","zh-TW":"農民組成了一個合作社，以為其農產品談判更好的價格。"},{"en":"A consumer cooperative passes savings directly to its members.","zh-TW":"消費者合作社將節省直接轉給其成員。"}]', '{"adjective":"cooperative"}', NULL, 4, 1544, NULL),
(1545, 'coordinate', '/kəʊˈɔːrdɪneɪt/', 'verb', '{"zh-TW":["協調；統籌"],"en":["to organize different elements to work together effectively"]}', '{"prefix":{"text":"co-","meaning":"together (一起)"},"root":{"text":"ordin","meaning":"order (秩序)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使一起有秩序，即「協調」。"}', 'coordinate efforts/activities/schedules', '[{"en":"She coordinates all logistics for international shipments.","zh-TW":"她協調所有國際出貨的物流。"},{"en":"We need to coordinate our efforts across departments.","zh-TW":"我們需要跨部門協調努力。"}]', '{"noun":"coordination","noun2":"coordinator"}', NULL, 4, 1545, 93),
(1546, 'coordination', 'koʊˌɔːrdɪˈneɪʃən', 'noun', '{"zh-TW":["協調；配合","統籌"],"en":["the organization of people or tasks","working together smoothly"]}', NULL, 'project coordination/team coordination', '[{"en":"Good coordination is essential.","zh-TW":"良好的協調至關重要。"}]', '{"verb":"coordinate","adjective":"coordinated","adverb":"coordinately"}', NULL, 4, 1546, 534),
(1547, 'coordination meeting', '/koʊˌɔːrdɪˈneɪʃən ˈmiːtɪŋ/', 'noun', '{"zh-TW":["協調會議"],"en":["a meeting held to synchronize activities across teams or departments"]}', NULL, 'hold a coordination meeting / weekly coordination meeting', '[{"en":"A weekly coordination meeting ensures all teams are aligned.","zh-TW":"每週協調會議確保所有團隊保持一致。"},{"en":"The coordination meeting resolved the inter-departmental scheduling conflict.","zh-TW":"協調會議解決了部門間的排程衝突。"}]', NULL, NULL, 5, 1547, NULL),
(1548, 'coordinator', '/koʊˈɔːrdɪneɪtər/', 'noun', '{"zh-TW":["協調員；統籌人員"],"en":["a person who organizes and manages activities within a team"]}', NULL, 'project coordinator / event coordinator / HR coordinator', '[{"en":"The project coordinator tracked deliverables and managed stakeholder communications.","zh-TW":"項目協調員追蹤可交付成果並管理利益相關者溝通。"},{"en":"She started as an HR coordinator before becoming a manager.","zh-TW":"她在成為經理前從人力資源協調員做起。"}]', '{"plural":"coordinators","verb":"coordinate"}', NULL, 4, 1548, NULL),
(1549, 'cope', '/koʊp/', 'verb', '{"zh-TW":["應付；處理"],"en":["to deal with something effectively"]}', '{"root":{"text":"cope","meaning":"strike/deal with (對付)"},"logic":"源自古法語 couper（打擊），引申為應對。"}', 'cope with / unable to cope', '[{"en":"She learned to cope with stress through meditation.","zh-TW":"她學會透過冥想來應對壓力。"},{"en":"He couldn''t cope with the workload.","zh-TW":"他無法應付工作量。"}]', '{"noun":"coping"}', NULL, 1, 1549, NULL);